    {% include sections/delta-section.html data=page.delta %}
  Data: heading (req), intro?, footnote?, tone?, visual?, prev{tag,name,year},
        current{tag,name,year}, hardware[], software[]
{%- endcomment -%}
{%- assign data = include.data -%}
{%- assign visual = data.visual | default: 'delta' -%}
<section class="wiki-section delta" data-tone="{{ data.tone | default: 'a' }}" id="delta-section">
  <div class="wiki-section-inner">
    <div class="wiki-section-eyebrow">{% include icon.html name="chart-column-stacked" %} Changes &amp; Improvements</div>
    <h2 class="wiki-section-title" style="margin-bottom:24px;">{{ data.heading }}</h2>
    {%- if data.intro -%}<div class="delta-prose"><p>{{ data.intro }}</p></div>{%- endif -%}
    {% include visual.html type=visual data=data %}
    {%- if data.footnote -%}<div class="gd-foot">{{ data.footnote }}</div>{%- endif -%}
  </div>
</section>

includes.sections/hero.html:
{%- comment -%}
  HERO — the page header band. UNIVERSAL: one include for BOTH variants
  (home page AND interior/sub-page). Structure is single-source here; each
  sub-piece (stats, search, spotlight, feature) is its own partial under
  _includes/hero/ so editing any one place propagates to every page — and
  to the build kit, which emits this same `hero:` data contract.

  Usage:  {% include sections/hero.html data=page.hero %}

  Data (all optional unless noted):
    ── CONTENT (contributor) ──
    title        REQUIRED — H1 (the trailing period accent is automatic)
    subtitle     optional sub-h1 line under the H1 (universal `title` role)
    subtitle_meta  optional mono tag appended after a " · " separator
                   (e.g. a model number / edition — the iPod "Model A2178")
    eyebrow      small mono category tag
    desc         one-paragraph lead
    search       true → render the search bar (HOME heroes only)
    search_placeholder   the search input placeholder
    stats        list of { num, label } (the 1×4 grid)
    feature      treatment-2 aside (see hero/feature.html)   } pick at most
    spotlight    treatment-1 aside (see hero/spotlight.html) } one aside
    ── DECORATION (skin / admin) ──
    bg           hero background (colour/gradient)
    accent       sets --hero-title-accent + --hero-eyebrow-dot
    chrome       named shared decoration block (currently: "ipod" device art)
    icon         corner wiki-icon sprite name
    overlays     list of inline-style strings → decorative overlay divs
    watermark    raw HTML for a skin ghost watermark
    id           section id (e.g. "overview")
    class        extra classes for skin flourishes (e.g. "scan")
{%- endcomment -%}
{%- assign h = include.data -%}
{%- capture herostyle -%}{%- if h.bg %}background:{{ h.bg }};{% endif %}{%- if h.accent %}--hero-title-accent:{{ h.accent }};--hero-eyebrow-dot:{{ h.accent }};{% endif %}{%- endcapture -%}
{%- assign herostyle = herostyle | split: ';' | join: ';' -%}<section class="wiki-hero{% if h.class %} {{ h.class }}{% endif %}"{% if h.id %} id="{{ h.id }}"{% endif %}{% if herostyle != "" %} style="{{ herostyle }}"{% endif %}>
  {%- if h.watermark %}{{ h.watermark }}{% endif -%}
  {%- if h.chrome %}{% capture chromefile %}hero/chrome-{{ h.chrome }}.html{% endcapture %}{% include {{ chromefile }} %}{% endif -%}
  {%- if h.overlays %}{% for ov in h.overlays %}<div class="pointer-events-none absolute inset-0" style="{{ ov }}"></div>{% endfor %}{% endif -%}
  {%- if h.icon %}{% include icon.html name=h.icon %}{% endif -%}
  <div class="wiki-hero-inner">
    <div class="wiki-hero-content">
      {%- if h.eyebrow %}<div class="wiki-hero-eyebrow"><span class="wiki-hero-eyebrow-dot"{% if h.dot %} style="background:{{ h.dot }}"{% endif %}></span> {{ h.eyebrow }}</div>{% endif -%}
      <h1 class="wiki-hero-title">{{ h.title }}<span class="wiki-hero-title-accent">.</span></h1>
      {%- if h.subtitle %}<div class="wiki-hero-subtitle">{{ h.subtitle }}{% if h.subtitle_meta %}<span class="wiki-hero-subtitle-sep"> · </span><span class="wiki-hero-subtitle-meta">{{ h.subtitle_meta }}</span>{% endif %}</div>{% endif -%}
      {%- if h.desc %}<p class="wiki-hero-desc">{{ h.desc }}</p>{% endif -%}
      {%- if h.search %}{% include hero/search.html data=h %}{% endif -%}
      {%- if h.stats %}{% include hero/stats.html data=h.stats %}{% endif -%}
      {%- if h.extra %}{{ h.extra }}{% endif -%}
    </div>
    {%- if h.feature %}<aside class="wiki-hero-aside">{% include hero/feature.html data=h.feature %}</aside>{% endif -%}
    {%- if h.spotlight %}<aside class="wiki-hero-aside">{% include hero/spotlight.html data=h.spotlight %}</aside>{% endif -%}
  </div>
</section>

includes.sections/os-section.html:
{%- comment -%}
  OS SECTION (a page-section type — the framing, not the ribbon).
  The chrome a contributor gets on dropping an "Operating system support section":
    · locked eyebrow "Operating system support" + the locked layers icon
    · a required H2 heading
    · optional lead paragraphs (prose)
    · the lifecycle ribbon (the lane visual) in the slot
  Hosts the reusable `lane` visual. Usage:
    {% include sections/os-section.html data=page.os %}
  Data: heading (req), paragraphs?, tone?, visual?, + the lane data
        (title, segments[], notes[], weighted?, range_note?)
{%- endcomment -%}
{%- assign data = include.data -%}
{%- assign visual = data.visual | default: 'lifecycle-lane' -%}
<section class="wiki-section lane-section" data-tone="{{ data.tone | default: 'a' }}" id="os-section">
  <div class="wiki-section-inner">
    <div class="wiki-section-eyebrow">{% include icon.html name="layers" %} Operating system support</div>
    <h2 class="wiki-section-title" style="margin-bottom:24px;">{{ data.heading }}</h2>
    {%- if data.paragraphs -%}<div class="lane-prose wiki-section-prose">{% for p in data.paragraphs %}<p>{{ p }}</p>{% endfor %}</div>{%- endif -%}
    {% include visual.html type=visual data=data %}
  </div>
</section>

includes.sections/timeline-section.html:
{%- comment -%}
  TIMELINE SECTION (a page-section type — the framing, not the visual).
  The chrome a contributor gets on dropping a "Timeline section":
    · locked eyebrow "Timeline" + the locked move-horizontal icon
    · an OPTIONAL H2 heading
    · an auto-derived scroll hint (first → last event date range)
    · a full-bleed slot (the scroller bleeds edge-to-edge — locked)
  The visual that fills the slot (today: the one timeline) is routed through
  the dispatcher. Usage: {% include sections/timeline-section.html data=page.timeline %}
  Data: heading?, visual?, tone?, events[]
{%- endcomment -%}
{%- assign data = include.data -%}
{%- assign visual = data.visual | default: 'timeline' -%}
{%- assign first = data.events | first -%}
{%- assign last = data.events | last -%}
<section class="wiki-section timeline" data-tone="{{ data.tone | default: 'b' }}" id="tl-section">
  <div class="wiki-section-inner">
    <div class="tl-hdr">
      <div class="wiki-section-eyebrow tl-label">{% include icon.html name="move-horizontal" %} Timeline</div>
      {%- if data.heading -%}<h2 class="wiki-section-title" style="margin-bottom:24px;">{{ data.heading }}</h2>{%- endif -%}
      {%- if data.events.size > 1 -%}<div class="tl-scroll-hint jb">Scroll &middot; {{ first.month }} {{ first.year }} &ndash; {{ last.month }} {{ last.year }}</div>{%- endif -%}
    </div>
    {% include visual.html type=visual data=data %}
  </div>
</section>

includes.visual.html:
{%- comment -%}
  VISUAL DISPATCHER (Level-B engine entry point)
  Usage:  {% include visual.html type="catalog" data=page.catalog %}
  Routes a visual TYPE + its data to the matching bank component partial.
  Registry of types lives in _data/visuals.yml. To add a bank, add a
  `when` below + the partial (Jekyll's include needs a literal path, so the
  routing is an explicit case rather than a dynamic include).
{%- endcomment -%}
{%- case include.type -%}
  {%- when 'catalog' -%}{%- include visuals/catalog/catalog.html data=include.data -%}
  {%- when 'timeline' -%}{%- include visuals/timeline/timeline.html data=include.data -%}
  {%- when 'config' -%}{%- include visuals/config/config.html data=include.data -%}
  {%- when 'delta' -%}{%- include visuals/delta/delta.html data=include.data -%}
  {%- when 'spec' -%}{%- include visuals/spec/spec.html data=include.data -%}
  {%- when 'lifecycle-lane' -%}{%- include visuals/lifecycle-lane/lifecycle-lane.html data=include.data -%}
  {%- else -%}<!-- visual bank: unknown type "{{ include.type }}" (not in _data/visuals.yml) -->
{%- endcase -%}

includes.visuals/catalog/catalog.html:
{%- comment -%}
  CATALOG visual (Level B: data in → HTML out) — the list that fills a
  catalog-section's slot. It renders ONLY the visual: the masonry of
  category cards, each item's hidden detail content, and the shared
  expandable-card modal. The section's framing (eyebrow / summary / foot-
  note) lives in _includes/sections/catalog-section.html, not here.

  Colour: each category either references a skin swatch by number
  (`color: 3`) or, if it names none, auto-cycles the skin palette. The
  card/pill only ever read `--cat-color` — the swatch set lives in the skin.

  Data shape (per category): name, color?, ribbon?, note?, items[]
    ribbon: "string" (accent-colored) OR {text:, tone:}  (tone "gone" = grey)
    item: name, status?, info?, desc, groups?[], callout?, notes?, cta?
      group: label, pills[]  (pill = "string" OR {text:, struck:true})
      callout: {label, text}
{%- endcomment -%}
{%- assign data = include.data -%}
<div class="cat-masonry">
  {%- for cat in data.categories -%}
    {%- if cat.color -%}{%- assign accent = cat.color -%}{%- else -%}{%- assign accent = forloop.index0 | modulo: 8 | plus: 1 -%}{%- endif -%}
    {%- assign n = cat.items | size -%}
    {%- comment -%} ribbon can be a plain string (accent-colored) or {text, tone}. tone "gone" locks to the skin's grey "phased out" token. {%- endcomment -%}
    {%- assign rb_text = cat.ribbon.text | default: cat.ribbon -%}
    {%- assign rb_tone = cat.ribbon.tone | default: 'accent' -%}
    <div class="cat-card{% if cat.ribbon %} has-ribbon{% endif %}" style="--cat-color:var(--cat-accent-{{ accent }})">
      {%- if cat.ribbon -%}<div class="cat-ribbon{% if rb_tone == 'gone' %} ribbon-gone{% endif %}"><span>{{ rb_text }}</span></div>{%- endif -%}
      <div class="cat-card-title">{{ cat.name }}</div>
      <div class="cat-card-count">{{ n }} item{% if n != 1 %}s{% endif %}{% if cat.note %} &middot; {{ cat.note }}{% endif %}</div>
      <div class="cat-card-divider"></div>
      <div class="cat-card-pills">
        {%- assign ci = forloop.index0 -%}
        {%- for item in cat.items -%}
          <button type="button" class="cat-pill" data-detail="d-{{ ci }}-{{ forloop.index0 }}" data-color="var(--cat-accent-{{ accent }})"{% if cat.ribbon %} data-ribbon="{{ rb_text | escape }}" data-ribbon-tone="{{ rb_tone }}"{% endif %}>{{ item.name }}</button>
        {%- endfor -%}
      </div>
    </div>
  {%- endfor -%}
</div>

{%- comment -%} hidden per-item detail content, cloned into the modal on click {%- endcomment -%}
<div class="cat-details">
  {%- for cat in data.categories -%}
    {%- assign ci = forloop.index0 -%}
    {%- for item in cat.items -%}
      <div id="d-{{ ci }}-{{ forloop.index0 }}">
        <div class="modal-headrow">
          <span class="modal-eyebrow">{{ cat.name }}</span>
          {%- if item.status -%}<span class="chip st-{{ item.status }}">{{ item.status | capitalize }}</span>{%- endif -%}
          {%- if item.info -%}<span class="chip info">{{ item.info }}</span>{%- endif -%}
        </div>
        <h3 class="modal-title">{{ item.name }}</h3>
        <div class="modal-divider"></div>
        <p class="modal-desc">{{ item.desc }}</p>
        {%- for grp in item.groups -%}
          <div class="modal-group-label">{{ grp.label }}</div>
          <div>{%- for p in grp.pills -%}{%- if p.text -%}<span class="gpill{% if p.struck %} struck{% endif %}">{{ p.text }}</span>{%- else -%}<span class="gpill">{{ p }}</span>{%- endif -%}{%- endfor -%}</div>
        {%- endfor -%}
        {%- if item.callout -%}<div class="modal-callout"><div class="modal-callout-label">{{ item.callout.label }}</div><div class="modal-callout-text">{{ item.callout.text }}</div></div>{%- endif -%}
        {%- if item.notes -%}<div class="modal-note">{{ item.notes }}</div>{%- endif -%}
        {%- comment -%} CTA is canon — always present. Links only once the item has a real page; until then it's inert (click does nothing). {%- endcomment -%}
        <div class="modal-divider is-inset"></div>
        <a class="modal-cta"{% if item.cta %} href="{{ item.cta }}"{% endif %}>See full entry &rarr;</a>
      </div>
    {%- endfor -%}
  {%- endfor -%}
</div>

{%- comment -%} shared expandable-card modal shell {%- endcomment -%}
<div class="modal-ov" data-catalog-modal>
  <div class="modal-card">
    <div class="cat-ribbon" data-modal-ribbon></div>
    <button type="button" class="modal-close" data-modal-close aria-label="Close">&times;</button>
    <div class="modal-scroll" data-modal-body></div>
  </div>
</div>

<script>
(function(){
  if(window.__catalogBank)return; window.__catalogBank=1;
  function closeAll(){var o=document.querySelectorAll('[data-catalog-modal].open');for(var i=0;i<o.length;i++)o[i].classList.remove('open');}
  document.addEventListener('click',function(e){
    var pill=e.target.closest('.cat-pill[data-detail]');
    if(pill){
      var modal=document.querySelector('[data-catalog-modal]');
      var card=modal.querySelector('.modal-card');
      var d=document.getElementById(pill.getAttribute('data-detail'));
      if(!d)return;
      card.style.setProperty('--cat-color', pill.getAttribute('data-color')||'var(--cat-accent-1)');
      var rb=pill.getAttribute('data-ribbon');
      var rbEl=modal.querySelector('[data-modal-ribbon]');
      rbEl.innerHTML = rb ? '<span>'+rb+'</span>' : '';
      rbEl.classList.toggle('ribbon-gone', pill.getAttribute('data-ribbon-tone')==='gone');
      card.classList.toggle('has-ribbon', !!rb);
      modal.querySelector('[data-modal-body]').innerHTML = d.innerHTML;
      modal.querySelector('[data-modal-body]').scrollTop=0;
      modal.classList.add('open');
      return;
    }
    if(e.target.closest('[data-modal-close]')){closeAll();return;}
    if(e.target.hasAttribute('data-catalog-modal')){closeAll();return;}
  });
  document.addEventListener('keydown',function(e){if(e.key==='Escape')closeAll();});
})();
</script>

includes.visuals/config/config.html:
{%- comment -%}
  CONFIG visual (Level B) — the storage/configuration chart. One row per
  config: capacity · a fill bar whose width is DERIVED from the capacity
  (normalized to a common base so GB and TB stay proportional) · price
  (supports an "old → new" drop) · dates · device-colour dots. A `revised`
  flag stripes the bar and (on the first revised row) drops a labeled
  divider. No modal. Static — all math in Liquid, no JS.
  Item fields: capacity (number), unit? (GB|TB, default GB), model, price,
  dates, revised?, colors?[]{name,hex,ring?}.
{%- endcomment -%}
{%- assign data = include.data -%}
{%- comment -%} max capacity normalized to GB (1 TB = 1000 GB) for proportional bars {%- endcomment -%}
{%- assign maxgb = 1 -%}
{%- for it in data.items -%}
  {%- if it.unit == 'TB' -%}{%- assign cg = it.capacity | times: 1000 -%}{%- else -%}{%- assign cg = it.capacity | times: 1 -%}{%- endif -%}
  {%- if cg > maxgb -%}{%- assign maxgb = cg -%}{%- endif -%}
{%- endfor -%}
<div class="cfg-chart">
  <div class="cfg-chart-head"><div class="cfg-chart-title fr">{{ data.chart_title }}</div></div>
  <div class="cfg-bars">
    {%- assign divider_done = false -%}
    {%- for it in data.items -%}
      {%- if it.revised and divider_done == false -%}
        <div class="cfg-divider"></div>{%- if data.divider_label -%}<div class="cfg-divider-label jb">{{ data.divider_label }}</div>{%- endif -%}
        {%- assign divider_done = true -%}
      {%- endif -%}
      {%- if it.unit == 'TB' -%}{%- assign cg = it.capacity | times: 1000 -%}{%- else -%}{%- assign cg = it.capacity | times: 1 -%}{%- endif -%}
      {%- comment -%} bar width = exact proportion of the largest capacity (decimal, no floor) {%- endcomment -%}
      {%- assign w = cg | times: 100.0 | divided_by: maxgb | round: 2 -%}
      <div class="cfg-row">
        <div class="cfg-cap fr">{{ it.capacity }}<span>{{ it.unit | default: 'GB' }}</span></div>
        <div class="cfg-track"><div class="cfg-fill{% if it.revised %} cfg-fill-rev{% endif %}" style="width:{{ w }}%">{% if it.model %}<span class="cfg-model">{{ it.model }}</span>{% endif %}</div></div>
        {%- if it.price contains '→' -%}
          {%- assign pp = it.price | split: '→' -%}
          <div class="cfg-price fr"><div class="cfg-price-line">{{ pp[0] | strip }}</div><div class="cfg-price-line"><span class="cfg-price-arrow">→</span> {{ pp[1] | strip }}</div></div>
        {%- else -%}
          <div class="cfg-price fr"><div class="cfg-price-line">{{ it.price }}</div></div>
        {%- endif -%}
        {%- if it.dates -%}<div class="cfg-date-row"><span class="cfg-dates">{{ it.dates }}</span></div>{%- endif -%}
        {%- if it.colors -%}
        <div class="cfg-colors">
          {%- for c in it.colors -%}<div class="cfg-color"><span class="cfg-dot{% if c.ring %} ring{% endif %}" style="background:{{ c.hex }}"></span><span class="cfg-dot-name jb">{{ c.name }}</span></div>{%- endfor -%}
        </div>
        {%- endif -%}
      </div>
    {%- endfor -%}
  </div>
</div>

includes.visuals/delta/delta.html:
{%- comment -%}
  DELTA visual (Level B: data in → HTML out) — the side-by-side comparison
  table that fills a delta-section's slot. Renders the prev|current header
  + a Hardware section + a Software section, each a labelled row followed by
  its data rows (see row.html). The section frame (eyebrow / H2 / intro /
  footnote) lives in _includes/sections/delta-section.html.
  Data: prev{tag,name,year} · current{tag,name,year} · hardware[] · software[]
{%- endcomment -%}
{%- assign d = include.data -%}
{%- capture hwIcon -%}<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>{%- endcapture -%}
{%- capture swIcon -%}<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="2" width="14" height="20" rx="2" ry="2"/><line x1="12" y1="18" x2="12.01" y2="18"/></svg>{%- endcapture -%}
<div class="gd-wrap">
<table class="gd"><colgroup><col class="gd-c1"><col class="gd-c2"><col class="gd-c3"></colgroup>
<thead>
<tr class="gd-gen"><td class="gd-gen-label"></td><td class="gd-gen-old"><span class="gd-tag">{{ d.prev.tag }}</span><span class="gd-name">{{ d.prev.name }}</span><span class="gd-year">{{ d.prev.year }}</span></td><td class="gd-gen-new"><span class="gd-tag">{{ d.current.tag }}</span><span class="gd-name">{{ d.current.name }}</span><span class="gd-year">{{ d.current.year }}</span></td></tr>
</thead>
<tbody>
<tr class="gd-sec"><td class="gd-sec-main">{{ hwIcon }}Hardware</td><td class="gd-sec-col">{{ d.prev.name }}</td><td class="gd-sec-col">{{ d.current.name }}</td></tr>
{%- for r in d.hardware -%}{% include visuals/delta/row.html row=r %}{%- endfor -%}
<tr class="gd-sec"><td class="gd-sec-main">{{ swIcon }}Software</td><td class="gd-sec-col">{{ d.prev.name }}</td><td class="gd-sec-col">{{ d.current.name }}</td></tr>
{%- for r in d.software -%}{% include visuals/delta/row.html row=r %}{%- endfor -%}
</tbody></table>
</div>

includes.visuals/delta/row.html:
{%- comment -%}
  DELTA data row. row: label, old, new (HTML ok), no_old?, chip?, chip_text?
  chip is one of: better · feature · changed · worse · same (colour = the judgment).
{%- endcomment -%}
{%- assign r = include.row -%}
<tr class="gd-row"><td class="gd-label"><span class="gd-label-name">{{ r.label }}</span></td>{% if r.no_old %}<td class="gd-old"><span class="gd-dot"></span><span class="gd-old-val missing">{{ r.old | default: '—' }}</span></td>{% else %}<td class="gd-old"><span class="gd-old-val">{{ r.old }}</span></td>{% endif %}<td class="gd-new"><span class="gd-new-val">{{ r.new }}</span>{% if r.chip %}<span class="gd-chip gd-chip-{{ r.chip }}">{{ r.chip_text }}</span>{% endif %}</td></tr>

includes.visuals/lifecycle-lane/lifecycle-lane.ht:
{%- comment -%}
  LIFECYCLE-LANE visual (Level B) — a horizontal lifecycle ribbon. Fills an
  os-section host slot. Renders the lane-head (title + AUTO-derived range), the
  segmented ribbon, optional status notes, and an AUTO-derived legend.
  The section frame (eyebrow / H2 / lead prose) lives in the host section
  (e.g. _includes/sections/os-section.html).

  Data:
    title       (req)  lane-head left title
    weighted    (opt)  true → width ∝ time-to-next-segment (needs parseable
                       dates, e.g. "2019-05" or "May 1 2019"); default uniform
    end         (opt)  weighted mode only — right-edge date for the last
                       segment (else the last segment gets the median width)
    range_note  (opt)  editorial suffix appended to the auto "start → end"
    segments[]  (req)  each: ver, date, type(full|partial|dropped|security),
                       badge?, badge_type?(ship|paid|limited|final|dropped|security)
                       NB: a `security` tile = a post-EOL patch; place it AFTER
                       the dropped tile so the latest date stays last.
    notes[]     (opt)  each: status(full|partial|limited|final|dropped|security), label, text
{%- endcomment -%}
{%- assign d = include.data -%}
{%- assign segs = d.segments -%}
{%- comment -%} auto range: launch → the drop (first major it was dropped from);
   duration in years/months, rounded to nearest month. Anything after the drop
   (post-EOL security patches) is shown as a tile but excluded from the count. {%- endcomment -%}
{%- assign droplist = segs | where: "type", "dropped" -%}
{%- if droplist.size > 0 -%}
  {%- assign enddate = droplist.first.date -%}
{%- else -%}
  {%- assign live = segs | where_exp: "s", "s.type != 'security'" -%}
  {%- assign enddate = live.last.date -%}
{%- endif -%}
{%- assign e1 = segs.first.date | date: '%s' | plus: 0 -%}
{%- assign e2 = enddate | date: '%s' | plus: 0 -%}
{%- assign durmo = e2 | minus: e1 | plus: 1314873 | divided_by: 2629746 -%}
{%- assign dyr = durmo | divided_by: 12 -%}
{%- assign dmo = durmo | modulo: 12 -%}
{%- capture dur -%}{% if dyr > 0 %}{{ dyr }} yr {% endif %}{% if dmo > 0 %}{{ dmo }} mo{% endif %}{% if dyr == 0 and dmo == 0 %}&lt;1 mo{% endif %}{%- endcapture -%}
{%- assign dur = dur | strip -%}
{%- comment -%} version count = distinct MAJOR versions received (non-dropped tiles) {%- endcomment -%}
{%- assign majors = "" -%}
{%- for s in segs -%}{%- unless s.type == 'dropped' -%}{%- assign mj = s.ver | split: '.' | first -%}{%- assign majors = majors | append: mj | append: ',' -%}{%- endunless -%}{%- endfor -%}
{%- assign vcount = majors | split: ',' | uniq | size -%}
<div class="lane-wrap">
  <div class="lane-head">
    <div class="lane-title fr">{{ d.title }}</div>
    <div class="lane-range jb">{{ segs.first.date }} &rarr; {{ enddate }} &middot; {{ dur }} &middot; {{ vcount }} versions{% if d.range_note %} &middot; {{ d.range_note }}{% endif %}</div>
  </div>
  <div class="lane-scroll"><div class="lane {% if d.weighted %}weighted{% else %}uniform{% endif %}">
    {%- for s in segs -%}
      {%- assign segstyle = '' -%}
      {%- if d.weighted -%}
        {%- if forloop.last -%}
          {%- assign nextdate = d.end -%}
        {%- else -%}
          {%- assign ni = forloop.index0 | plus: 1 -%}
          {%- assign nextdate = segs[ni].date -%}
        {%- endif -%}
        {%- if nextdate -%}
          {%- assign e1 = s.date | date: '%s' | plus: 0 -%}
          {%- assign e2 = nextdate | date: '%s' | plus: 0 -%}
          {%- assign w = e2 | minus: e1 -%}
          {%- if w > 0 -%}{%- assign segstyle = 'flex:' | append: w -%}{%- endif -%}
        {%- endif -%}
      {%- endif -%}
      <div class="lane-seg {{ s.type }}"{% if segstyle != '' %} style="{{ segstyle }}"{% endif %}>
        {%- if s.badge -%}<span class="lane-badge {{ s.badge_type | default: 'ship' }}">{{ s.badge }}</span>{%- endif -%}
        <div class="lane-ver fr">{{ s.ver }}</div>
        <div class="lane-date jb">{{ s.date }}</div>
      </div>
    {%- endfor -%}
  </div></div>
  {%- if d.notes -%}
  <div class="lane-notes">
    {%- for n in d.notes -%}
    <div class="lane-note"><span class="lane-note-dot lane-dot-{{ n.status }}"></span><span><strong>{{ n.label }}</strong> &mdash; {{ n.text }}</span></div>
    {%- endfor -%}
  </div>
  {%- endif -%}
  {%- assign hasFull = segs | where: "type", "full" -%}
  {%- assign hasPartial = segs | where: "type", "partial" -%}
  {%- assign hasDropped = segs | where: "type", "dropped" -%}
  {%- assign hasSecurity = segs | where: "type", "security" -%}
  <div class="lane-legend">
    {%- if hasFull.size > 0 -%}<div class="lane-leg"><div class="lane-leg-sw lane-sw-full"></div>Full support</div>{%- endif -%}
    {%- if hasPartial.size > 0 -%}<div class="lane-leg"><div class="lane-leg-sw lane-sw-partial"></div>Partial</div>{%- endif -%}
    {%- if hasDropped.size > 0 -%}<div class="lane-leg"><div class="lane-leg-sw lane-sw-dropped"></div>Not supported</div>{%- endif -%}
    {%- if hasSecurity.size > 0 -%}<div class="lane-leg"><div class="lane-leg-sw lane-sw-security"></div>Security patch</div>{%- endif -%}
  </div>
</div>

includes.visuals/spec/spec.html:
